#!/usr/bin/env bash
#
# Purpose: build Docker images for the fullMeshExample SeedEMU output.
# Inputs: ./output/docker-compose.yml generated by compileFullMesh.sh.
# Outputs: Docker images and ./logs/dockerBuild build logs.
# Side effects: invokes the parent topology buildTest1.sh from this directory.
# Expected context: run from fullMeshExample after compileFullMesh.sh.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$SCRIPT_DIR"

if [[ ! -f ./output/docker-compose.yml ]]; then
    echo "missing ./output/docker-compose.yml; run ./compileFullMesh.sh first" >&2
    exit 1
fi

"$SCRIPT_DIR/../buildTest1.sh"
